35\81","\137\80\52\148\163\146\123\21")]=nil,[v7("\235\212\162\236\23\200\207\176","\99\152\160\195\158")]=nil};local v189={[v7("\172\50\207","\95\231\87\182\94\125")]=Enum[v7("\115\204\225\23\6\120\22","\115\56\169\152\84\105\28")]['F']};local v190={[v7("\20\202\168\97","\37\94\133\225\47\214")]={"Oh! Hello! I'm Shelly! I— sorry. Hi. Let's do this?","Huh?? OH! You're asking me? Yes! I'm ready! I've been ready! I was ready before!","Okay okay okay, new team! I have facts, I have a patch kit, and— that's the list. That's the list.","Hi! Shelly! Paleontologist! It's a whole thing and I love it!",v7("\126\148\69\74\66\208\95\91\83\148\69\81\23\217\67\93\95\148\80\81\69\148\66\86\94\199\23\30\121\219\66\30\81\219\68\30\67\220\95\77\23\199\70\91\84\221\80\87\84\213\90\82\78\149\22\124\66\192\22\87\89\148\81\91\89\209\68\95\91\149\22\109\67\193\82\71\94\218\81\31","\62\55\180\54"),"You can count on me! And I'm here for you! Both of those things!",v7("\212\242\104\193\77\75\170\87\187\251\104\210\71\69\163\90\187\206\45\199\79\87\238\26\233\255\104\203\91\4\168\26\237\245\61\212\75\80\171\90\187\223\37\201\86\77\161\21\250\246\36\223\3\4\157\15\250\238\33\213\86\77\173\26\247\246\49\135\2\105\161\8\239\246\49\134\71\73\161\15\242\245\38\199\78\72\183\90","\123\155\154\72\166\34\36\206"),v7("\241\146\47\162\44\210\147\120\138\101\213\215\55\182\41\194\159\49\173\49\212\208\60\182\38\195\159\53\186\54\195\211\62\227\53\212\208\40\166\55\202\198\118\227\22\206\218\52\175\60\135\159\30\172\54\213\214\52\170\36\200\158\120\144\45\195\211\52\186\101\224\208\43\176\44\202\214\57\173\100","\69\166\191\88\195"),"Let's do this! And if I talk too much, just— wave? No. That's rude. Just say it. Politely. Please be polite.","I'm trying my best! Starting now! That was— that was me starting!",v7("\150\113\47\91\199\246\28\143\184\126\55\3\198\159\110\130\184\108\43\2\135\246\62\134\184\116\110\67\136\178\110\131\173\58\39\81\198\187\33\153\173\118\55\2\140\163\61\158\249\105\58\67\159\191\32\141\249\116\43\67\148\246\55\133\172\59","\234\217\26\78\34\230\214\78"),"Hello! I'm the fossil one! Not a seashell! Sorry— nobody said seashell. Nevermind!"},[v7("\153\59\196\114","\42\208\127\136\55")]={"Fun fact! Ammonites made it through three whole periods! That's a lot of periods to keep track of!","The Oviraptor got called an egg thief for about seventy years! Not seventy exactly! But— years!","Raptors probably had feathers! Probably! We're still arguing! I'm not arguing! I'm just very invested!",v7("\66\87\196\44\230\237\66\124\87\199\32\178\233\15\98\80\204\37\170\255\15\102\93\219\44\230\237\92\49\90\192\46\230\237\92\49\89\137\42\167\254\14\49\118\198\61\230\225\70\127\93\136\105\139\229\65\116\24\192\58\230\248\71\116\24\219\44\161\249\67\112\74\137\58\175\246\74\48","\47\17\56\169\73\198\140"),"The Cambrian explosion wasn't an explosion! It was very slow! Slightly disappointing! Still cool though!","T. rex teeth were like bananas! Not the taste! The— nevermind. Bananas.",v7("\6\60\82\76\190\129\55\39\79\3\186\133\48\48\28\66\191\143\55\59\88\3\171\143\48\117\93\3\165\149\44\49\78\70\169\192\35\59\88\3\190\137\58\33\69\14\171\137\52\48\28\78\164\140\46\60\83\77\237\153\39\52\78\80\236\192\16\58\73\68\165\140\59\116\28\106\237\146\45\32\82\71\237\132\45\34\82\3\185\143\98\55\89\3\190\129\36\48\29","\224\66\85\60\35\205"),"People thought the Stegosaurus had a second brain! It didn't! That rumour got around!",v7("\209\122\125\87\34\69\210\250\63\104\82\40\72\215\184\55\101\27\52\66\192\235\51\112\27\49\66\223\244\63\127\79\59\66\221\185\122\72\83\55\67\147\209\122\122\84\39\67\215\184\59\60\85\55\90\147\254\53\111\72\59\65\147\249\52\120\27\32\88\218\246\63\120\27\38\69\214\184\45\116\84\62\72\147\235\35\111\79\55\64\146","\179\152\90\28\59\82\45"),"I've been cleaning this fossil for three days! It's not even my fossil! It's a practice fossil!",v7("\141\251\56\64\84\75\188\178\55\14\66\83\233\240\53\18\73\87\233\243\46\5\13\80\172\241\52\14\68\71\168\254\48\25\13\64\160\252\51\19\76\81\187\225\99\64\121\65\170\250\50\9\78\69\165\254\37\65\13\109\233\225\61\25\13\77\189\178\61\64\65\75\189\179\124\51\66\86\187\235\125","\36\201\146\92\96\45"),"I know way too much about extinction! It's a conversation killer! Literally! Haha.","I have a favourite dinosaur but it changes! Every week! Currently it's a secret!",v7("\222\139\234\77\197\227\163\177\198\206\177\5\202\248\232\249\224\200\250\11\132\222\188\230\232\213\189\79\209\228\232\177\253\206\244\75\207\254\242\246\169\199\255\74\209\227\188\229\225\195\189\102\214\242\232\240\234\195\242\80\215\185\188\223\230\212\240\68\200\183\232\249\224\200\250\86\133","\145\137\166\157\37\164\151\156"),"This is going well! I think! I don't have data! But I feel it!",v7("\33\22\72\61\155\85\78\20\70\127\211\125\0\28\6\60\242\52\2\22\81\121\155\121\15\26\79\117\213\113\29\88\7\75\222\120\2\85\7\85\155\120\1\15\66\60\221\125\0\16\84\116\210\122\9\89\83\116\222\121\79","\20\110\121\39\28\187"),"If a twisted shows up, shout! I'll come running! I'll try to run fast!",v7("\45\249\1\36\95\92\187\1\228\22\103\71\8\163\3\248\10\38\21\92\139\78\230\11\53\70\5\226\15\243\11\50\64\92\171\26\176\68\14\20\11\173\28\227\29\103\85\30\173\27\229\68\42\93\18\167\78\229\11\40\24\92\170\1\255\1\52\64\16\187\64","\194\110\145\100\71\52\124"),"Stamina is not my strongest stat! I know that! I've read my own numbers!","My ability boosts extraction by seventy-five percent for fifteen seconds! I'm telling you in case you— need it!",v7("\91\169\76\175\210\28\27\5\125\169\73\175\202\0\27\5\126\224\64\171\215\89\73\19\115\237\93\239\132\55\84\20\125\237\93\238\204\24\72\86\119\255\65\188\132\24\72\29\119\237\4\186\203\89\72\19\119\169\80\166\193\89\72\26\123\237\65\189\138","\118\18\137\36\206\164\121\59"),"I'm not scared, I'm just— aware! Highly aware! Of the hallway!",v7("\219\207\230\6\85\190\223\239\27\67\236\153\234\7\12\252\216\240\29\79\255\213\239\13\12\255\153\231\29\75\190\202\234\0\73\191\153\198\25\92\234\192\175\84\72\235\202\247\13\0\190\214\224\23\77\237\208\236\26\77\242\213\250\84\72\255\215\228\17\94\241\204\240\85\12\212\204\240\0\12\242\208\232\17\12\250\208\228\7\13","\44\158\185\131\116"),"Pterosaurs are not dinosaurs! I will not elaborate! Okay, I'll elaborate later!",v7("\101\202\206\114\204\162\117\12\158\213\126\200\231\97\77\158\222\127\155\170\104\95\143\209\113\154\231\69\68\152\216\114\155\166\101\88\143\208\103\207\180\48\12\190\213\114\155\179\121\69\152\217\55\212\169\116\12\130\216\123\223\230","\17\44\234\189\23\187\199"),"I'm learning to sew! From a friend! It's going! It's going okay!","Nobody's listening and that's— fine! Totally fine! I'll just keep talking!",v7("\19\113\158\19\56\107\158\15\33\123\204\74\49\123\219\6\119\119\208\28\62\109\215\8\59\123\129\74\25\113\129\74\24\117\223\19\118\62\249\24\50\127\202\75\119\80\209\24\58\127\210\75","\106\87\30\190"),v7("\255\172\11\121\222\23\86\212\215\248\76\125\138\91\77\200\152\162\66\60\194\86\74\221\222\237\66\50\132","\188\182\140\108\28\170\55\34"),"Nevermind— it was never fun anyway! Kidding! Mostly!","If I go quiet, I'm counting exits. Two of them. Probably three.","Small steps! Big machine! That's the entire trick!","You're doing great! I mean it! I analyzed nothing but I mean it!",v7("\245\244\224\226\202\177\168\226\156\160\224\230\211\166\241\163\200\188\233\247\156\177\254\230\206\173\252\235\213\186\239\163\212\177\250\230\156\189\251\163\221\244\234\234\200\244\231\245\217\166\235\236\211\191\237\231\157\244\219\243\213\166\225\247\201\181\228\239\197\245","\131\188\212\136"),"There's dust on my shell! From the dig site! The digging is imaginary!",v7("\160\75\101\52\95\153\27\116\34\22\134\5\49\40\89\157\3\120\40\81\200\75\88\50\22\129\10\97\54\83\135\24\48\102\123\134\29\120\40\81\201\4\127\103","\54\233\107\17\70"),"I'm behind you! In a support way! Not a creepy way!","Two hands on the machine! Metaphorically! I'm not making it weird!","I could talk about the Mesozoic for an hour! I'll spare you! This time!","If you're bored, I can be boring quieter! I have that setting!","I brought a spare patch kit! It's never useful! It's never not useful!","It's quiet! I like quiet! I'm going to keep talking over it!",v7("\217\104\60\23\203\228\45\107\1\203\231\38\107\4\132\246\41\40\17\132\241\38\47\69\208\248\45\37\69\200\255\59\63\69\208\248\45\107\21\197\224\45\57\68\132\220\39\56\17\132\228\39\107\13\205\227\60\36\23\221\177\104\31\23\197\247\33\40\68","\164\144\72\75\101"),v7("\211\131\14\154\236\81\238\153\86\155\159\119\188\156\78\201\159\83\245\135\74\201\159\95\235\138\86\155\159\119\242\203\91\210\218\30\223\153\74\206\222\93\249\132\90\201\158\30\209\142\65\206\222\82\240\146\14","\62\156\235\47\186\191"),"Are we doing well? I think we're doing well! No data! But yes!","I'd rather dig than fight! Honestly I'd rather neither!","Nobody picks me first! That's fine! It's fine. It's— it's fine.","I'm a mollusk, technically! With hobbies! With a patch kit!","A brachiosaurus neck is longer than— a lot of things! That's a fact!","I keep thinking someone's about to say my name! Awkward!"},[v7("\37\207\207\19\248\152\0\195\62\222","\140\109\138\142\65\172\199\76")]={"Oh no— are you alright? Answer honestly! I'll wait right here!","Please, please, please don't panic! I know that's not how panic works! Please anyway!","Okay! New plan! Slower! Smaller steps! I'll stop saying calm!","That was one heart! That's— that's a lot! Come stand over here with me!","Please don't cry! I know you're not crying! I'm preemptively saying it!","I should have said something sooner! I'm sorry! I noticed the corner!","Ouch! New plan! The old plan was bad! I'm sorry, old plan!","Careful! One more of those is not a joke! I'm not joking around about it!",v7("\213\76\178\28\253\201\177\183\88\190\15\250\213\245\183\115\182\30\225\200\186\242\30\187\28\253\196\166\182\30\149\15\236\192\160\255\87\185\26\169\200\167\183\74\191\24\169\209\166\254\81\165\20\253\216\24