stly this!","Attach that to my record! I have a record! It's new!","I'd like this formally noted! Consider it noted!"},[v7("\47\170\117\153\203","\30\105\230\58\214\153\203")]={"Hooray! I'm not extinct!",v7("\61\23\225\242\6\167\28\29\228\243\64\152\18\31\243\242\16\167\18\28\183\242\52\163\22\82\230\190\1\165\83\27\229\242\19\191\18\11\255\188\7\235\29\23\247\160\64\178\28\7\183","\203\115\114\150\210\96"),v7("\250\172\95\48\198\224\88\127\209\233\28\62\192\255\89\50\209\224\85\49\212\172\90\48\192\255\85\51\192\172\78\54\212\228\72\127\221\227\75\113\157\162","\95\179\140\60"),v7("\4\255\48\245\217\20\160\217\46\253\98\182\236\22\161\209\51\255\99\244\217\90\165\144\49\239\42\243\200\90\171\222\37\187\99\198\208\31\165\195\37\187","\176\64\154\67\150\188\122\196"),v7("\12\90\100\128\87\189\54\65\33\129\66\189\38\65\45\157\94\248\33\22\100\174\70\248\38\66\100\129\79\233\32\91\101\205\99\242\51\64\42\138\14\251\44\91\55\153\15","\157\69\41\68\237\46"),v7("\5\186\228\255\251\220\193\108\248\226\176\237\220\192\45\244\238\254\233\144\196\108\252\232\227\253\217\201\108\232\238\247\230\196\133\34\245\240\177\174\249\203\63\238\226\241\234\145\133\24\242\238\227\175","\165\76\154\135\144\142\176"),v7("\12\40\85\2\83\87\188\100\42\72\71\18\71\184\45\35\6\71\32\65\160\45\35\64\71\27\69\171\33\109\80\2\83\71\182\100\44\64\6\26\78\248","\217\68\77\39\103\115\32"),"Everyone here? Count off! I'll count! ...I counted wrong!","One floor closer! We're doing okay! I'm choosing to believe that!",v7("\131\137\169\205\215\227\159\169\131\187\156\146\221\214\180\152\169\211\146\247\208\181\204\170\210\221\229\204\179\137\188\206\147\177\240\181\204\168\210\146\255\208\179\204\160\212\193\229\218\169\205\236\248\219\229\215\162\158\236\202\211\232\158","\191\199\236\204\189\178\145"),v7("\82\143\91\73\115\148\88\65\98\198\91\67\121\137\79\3\54\149\92\66\115\198\91\78\117\146\78\14\54\175\29\71\119\144\88\15\101\137\29\66\119\136\68\15\112\135\94\91\101\199","\47\22\230\61"),v7("\44\1