\162\37\224\16\142\225\159\237\166\42\241\85\138\237\209\231\189\33\240\85\147\237\218\240\187\45\251\27\145\185","\226\152\191\131\207\68\148\117"),"I offered Vee a dinosaur fact and got— nothing! Polite nothing!","Vee and I are past and future! That's on a poster! I've seen the poster!","I don't think Vee sees me standing here! That's okay! I'll stand somewhere else!","Past and future! We're a matching set! One of us got the poster!","Vee's channel would be great! Even if it's just static, I'd watch it!"},[v7("\46\100\146\252\106\61\100\136\224\113\35","\53\122\43\221\178")]={v7("\201\167\11\12\172\10\69\53\239\161\26\94\174\28\22\53\231\164\13\94\169\1\0\102\226\161\21\27\232\0\14\35\226\173\10\17\166\0\69\39\224\172\94\55\232\27\4\34\174\188\17\94\171\28\23\52\235\171\10\94\160\26\8\103\174\152\17\18\161\7\0\42\247\233","\70\142\200\126\126\200\115\101"),"Well— not all fossils are skeletal remains actually! Just most! Don't be discouraged!","It's not a bad thing! Variation in data is key to new discoveries!",v7("\116\33\82\208\232\74\110\68\195\224\95\61\7\207\233\19\3\78\209\255\19\8\72\209\255\90\34\78\195\226\18\110\110\130\228\82\56\66\130\237\19\58\78\214\224\86\111\7\227\172\67\33\75\203\248\86\110\72\204\233\18","\140\51\78\39\162"),v7("\47\130\203\225\252\243\254\194\0\130\211\245\226\163\247\206\26\214\222\230\177\243\231\206\29\199\201\226\240\247\252\196\0\130\212\240\245\240\181\223\6\195\213\180\243\236\251\206\29\131\155\209\231\234\241\206\0\193\222\171\177\213\252\201\11\209\154","\171\110\162\187\148\145\131\149"),v7("\150\2\62\92\70\168\77\34\93\2\165\5\46\14\64\180\30\63\14\65\190\1\36\91\80\241\2\37\14\86\185\8\107\72\78\190\2\57\15\2\146\2\37\72\75\181\8\37\90\2\190\31\42\64\69\180\76","\34\209\109\75\46"),v7("\58\185\175\179\246\23\185\156\179\239\1\253\162\252\245\29\252\251\186\251\16\237\251\189\244\23\185\178\177\247\22\253\178\189\238\22\245\162\252\251\3\246\183\179\253\26\227\190\184\186\21\246\169\252\243\7\184\251\140\232\28\254\16